/*
 * prog24_query_string_parser.c
 *
 * Original behaviour (observed from the binary):
 *
 *   * reads one line from stdin (up to 2048 bytes)
 *   * if nothing is read → prints "NO_INPUT" and exits
 *   * treats the line as an HTTP‑style query string:
 *         key1=val1&key2=val2&...
 *   * each key and each value is URL‑decoded:
 *         '+'  → space
 *         "%XY" → byte with hexadecimal value XY
 *   * after decoding, prints each pair on its own line as
 *         key=value
 *
 * The original binary was heavily obfuscated, but the logical
 * flow is exactly the simple parser above.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* ------------------------------------------------------------------ */
/* URL‑decode -------------------------------------------------------- */
/* ------------------------------------------------------------------ */
static void url_decode(const char *src, char *dst)
{
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            /* convert two hex digits */
            char hi = src[1];
            char lo = src[2];
            int val = 0;

            hi = (hi <= '9') ? hi - '0' : (hi & 0x5f) - 'A' + 10;   /* upper‑case */
            lo = (lo <= '9') ? lo - '0' : (lo & 0x5f) - 'A' + 10;

            val = (hi << 4) | lo;
            *dst++ = (char)val;
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

/* ------------------------------------------------------------------ */
/* Main ------------------------------------------------------------- */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* buffers – sizes are taken from the original binary (0x800 = 2048) */
    static char line[2048];
    static char key[1024];
    static char val[1024];

    /* ------------------------------------------------------------------
     * Read a line from stdin.
     * ------------------------------------------------------------------ */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and optional carriage‑return */
    size_t len = strlen(line);
    while (len && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        line[--len] = '\0';
    }

    /* ------------------------------------------------------------------
     * Parse the query string.
     * ------------------------------------------------------------------ */
    char *p = line;
    while (*p) {
        char *pair_end = strchr(p, '&');          /* end of this key/value pair */
        char *eq       = strchr(p, '=');          /* separator between key and value */

        /* Determine the limits of key and value strings */
        if (eq && (!pair_end || eq < pair_end)) {
            /* key = p … eq-1, value = eq+1 … (pair_end-1 or end) */
            size_t key_len = (size_t)(eq - p);
            memcpy(key, p, key_len);
            key[key_len] = '\0';
            if (pair_end) {
                size_t val_len = (size_t)(pair_end - (eq + 1));
                memcpy(val, eq + 1, val_len);
                val[val_len] = '\0';
            } else {
                strcpy(val, eq + 1);
            }
        } else {
            /* No '=', treat whole fragment as a key with empty value */
            if (pair_end) {
                size_t key_len = (size_t)(pair_end - p);
                memcpy(key, p, key_len);
                key[key_len] = '\0';
            } else {
                strcpy(key, p);
            }
            val[0] = '\0';
        }

        /* URL‑decode both parts */
        char decoded_key[1024];
        char decoded_val[1024];
        url_decode(key, decoded_key);
        url_decode(val, decoded_val);

        /* Output the pair */
        printf("%s=%s\n", decoded_key, decoded_val);

        /* Move to the next pair (skip the '&' if present) */
        if (pair_end)
            p = pair_end + 1;
        else
            break;
    }

    return 0;
}
